<script setup lang="ts">import{ref}from 'vue';import type{Study}from '../types/domain';defineProps<{studies:Study[];modelValue:number}>();defineEmits(['update:modelValue']);const active=(studies:Study[],id:number)=>studies.find(s=>s.id===id);</script><template><label class="study-select">试验底稿<select aria-label="试验底稿" :value="modelValue" @change="$emit('update:modelValue',Number(($event.target as HTMLSelectElement).value))"><option v-for="s in studies" :key="s.id" :value="s.id">{{s.code}} / {{s.name}}（底稿 v{{s.revision??0}}）</option></select><small v-if="active(studies,modelValue)" class="revision-badge fresh"><b>当前底稿 v{{active(studies,modelValue)!.revision??0}}</b><span>修订底稿会使旧研究标记为过期</span></small></label></template>
